insert into private.mission_variants_secure (
  variant_id,
  reference_solution,
  hidden_tests
)
select
  variant.id,
  '#include <algorithm>
#include <cmath>
#include <deque>
#include <iostream>
#include <memory>
#include <numeric>
#include <optional>
#include <queue>
#include <regex>
#include <string>
#include <unordered_map>
#include <unordered_set>
#include <utility>
#include <vector>
using namespace std;

class ListaEnlazada {
  struct Nodo {
    int valor;
    Nodo* siguiente;
  };
  Nodo* cabeza = nullptr;
  int largo_ = 0;

 public:
  ~ListaEnlazada() {
    while (cabeza) {
      Nodo* siguiente = cabeza->siguiente;
      delete cabeza;
      cabeza = siguiente;
    }
  }

  void agregar(int valor) {
    Nodo* nodo = new Nodo{valor, nullptr};
    if (!cabeza) cabeza = nodo;
    else {
      Nodo* actual = cabeza;
      while (actual->siguiente) actual = actual->siguiente;
      actual->siguiente = nodo;
    }
    ++largo_;
  }

  bool eliminar(int valor) {
    Nodo* anterior = nullptr;
    Nodo* actual = cabeza;
    while (actual) {
      if (actual->valor == valor) {
        if (anterior) anterior->siguiente = actual->siguiente;
        else cabeza = actual->siguiente;
        delete actual;
        --largo_;
        return true;
      }
      anterior = actual;
      actual = actual->siguiente;
    }
    return false;
  }

  bool contiene(int valor) const {
    Nodo* actual = cabeza;
    while (actual) {
      if (actual->valor == valor) return true;
      actual = actual->siguiente;
    }
    return false;
  }

  int largo() const { return largo_; }
};
',
  '[{"id":"list-missing","label":"Conserva el largo si no existe","expression":"[](){ ListaEnlazada l; l.agregar(3); return !l.eliminar(8) && l.largo() == 1; }()","expected":"true","feedback":"Solo reduce el largo cuando eliminas un nodo."}]'::jsonb
