#include <utility>
#include <vector>
using namespace std;

class Cola {
  deque<int> datos;

 public:
  void encolar(int valor) { datos.push_back(valor); }

  optional<int> desencolar() {
    if (datos.empty()) return nullopt;
    int valor = datos.front();
    datos.pop_front();
    return valor;
  }

  optional<int> frente() const {
    if (datos.empty()) return nullopt;
    return datos.front();
  }

  bool estaVacia() const { return datos.empty(); }
};
