select
  variant.id,
  'class ArbolBusqueda {
  constructor() {
    this.raiz = null;
  }
  insertar(valor) {
    const nodo = { valor, izquierda: null, derecha: null };
    if (!this.raiz) {
      this.raiz = nodo;
      return true;
    }
    let actual = this.raiz;
    while (true) {
      if (valor === actual.valor) return false;
      const lado = valor < actual.valor ? "izquierda" : "derecha";
      if (!actual[lado]) {
        actual[lado] = nodo;
        return true;
      }
      actual = actual[lado];
    }
  }
  contiene(valor) {
    let actual = this.raiz;
    while (actual) {
      if (valor === actual.valor) return true;
      actual = valor < actual.valor ? actual.izquierda : actual.derecha;
    }
    return false;
  }
}
