insert into private.mission_variants_secure (
  variant_id,
  reference_solution,
  hidden_tests
)
select
  variant.id,
  '#include <algorithm>
#include <cmath>
#include <deque>
#include <iostream>
#include <memory>
#include <numeric>
#include <optional>
#include <queue>
#include <regex>
#include <string>
#include <unordered_map>
#include <unordered_set>
#include <utility>
#include <vector>
using namespace std;

class ArbolBusqueda {
  struct Nodo {
    int valor;
    unique_ptr<Nodo> izquierda;
    unique_ptr<Nodo> derecha;
  };
  unique_ptr<Nodo> raiz;

 public:
  bool insertar(int valor) {
    unique_ptr<Nodo>* actual = &raiz;
    while (*actual) {
      if (valor == (*actual)->valor) return false;
      actual = valor < (*actual)->valor ? &(*actual)->izquierda : &(*actual)->derecha;
    }
    *actual = make_unique<Nodo>(Nodo{valor, nullptr, nullptr});
    return true;
  }

  bool contiene(int valor) const {
    const Nodo* actual = raiz.get();
    while (actual) {
      if (valor == actual->valor) return true;
      actual = valor < actual->valor ? actual->izquierda.get() : actual->derecha.get();
    }
    return false;
  }
};
',
  '[{"id":"tree-dupe","label":"Ignora duplicados","expression":"[](){ ArbolBusqueda a; return a.insertar(5) && !a.insertar(5); }()","expected":"true","feedback":"Retorna falso al recibir un valor existente."}]'::jsonb
