#include <queue>
#include <regex>
#include <string>
#include <unordered_map>
#include <unordered_set>
#include <utility>
#include <vector>
using namespace std;

int distanciaMinima(const vector<vector<int>>& grafo, int origen, int destino) {
  queue<pair<int, int>> cola;
  vector<bool> vistos(grafo.size(), false);
  cola.push({origen, 0});
  vistos[origen] = true;
  while (!cola.empty()) {
    auto [nodo, distancia] = cola.front();
    cola.pop();
    if (nodo == destino) return distancia;
    for (int vecino : grafo[nodo]) {
      if (!vistos[vecino]) {
        vistos[vecino] = true;
        cola.push({vecino, distancia + 1});
      }
    }
  }
  return -1;
}
',
