insert into private.mission_variants_secure (
  variant_id,
  reference_solution,
  hidden_tests
)
select
  variant.id,
  '#include <algorithm>
#include <cmath>
#include <deque>
#include <iostream>
#include <memory>
#include <numeric>
#include <optional>
#include <queue>
#include <regex>
#include <string>
#include <unordered_map>
#include <unordered_set>
#include <utility>
#include <vector>
using namespace std;

int minMonedas(const vector<int>& monedas, int monto) {
  const int infinito = monto + 1;
  vector<int> dp(monto + 1, infinito);
  dp[0] = 0;
  for (int actual = 1; actual <= monto; ++actual) {
    for (int moneda : monedas) {
      if (moneda <= actual) dp[actual] = min(dp[actual], dp[actual - moneda] + 1);
    }
  }
  return dp[monto] == infinito ? -1 : dp[monto];
}
',
  '[{"id":"coins-none","label":"Detecta un monto imposible","expression":"minMonedas({4, 6}, 5) == -1","expected":"-1","feedback":"Conserva los estados inalcanzables."},{"id":"coins-larger","label":"Optimiza un monto mayor","expression":"minMonedas({1, 5, 7}, 11) == 3","expected":"3","feedback":"Reutiliza las mejores soluciones anteriores."}]'::jsonb
